CREATE INDEX "shopping_lists_user_id_idx" ON "shopping_lists" ("user_id");
--> statement-breakpoint
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'shopping_lists_user_id_users_id_fk'
      AND conrelid = 'shopping_lists'::regclass
  ) THEN
    ALTER TABLE "shopping_lists" ADD CONSTRAINT "shopping_lists_user_id_users_id_fk"
      FOREIGN KEY ("user_id") REFERENCES "users"("id");
  END IF;
END $$;
